def get_db():
    if not DATABASE_URL:
        raise RuntimeError("DATABASE_URL is not configured.")

    # Fail reasonably quickly if PostgreSQL is unreachable instead of allowing a
    # web request or scheduled task to sit on a socket connect until Gunicorn's
    # much larger worker timeout expires. This does not change transaction
    # semantics; psycopg remains non-autocommit by default.
    return psycopg.connect(DATABASE_URL, connect_timeout=DB_CONNECT_TIMEOUT_SECONDS)

