functions.get_public_service_csrf:
def get_public_service_csrf(service_key):
    key = str(service_key or "").strip().upper()
    secret = str(FLASK_SECRET_KEY or "").encode("utf-8")
    message = f"ibrows-public-service-v89:{key}".encode("utf-8")
    return hmac.new(secret, message, hashlib.sha256).hexdigest()

functions.validate_public_service_csrf:
def validate_public_service_csrf(service_key):
    supplied = str(request.form.get("csrf_token") or "").strip()
    expected = get_public_service_csrf(service_key)
    if not supplied or not secrets.compare_digest(supplied, expected):
        abort(403)

