def admin_service_portfolio_upload(service_key):
    validate_csrf()
    service_key = str(service_key or "").upper()
    if service_key not in SERVICE_PORTFOLIO_DEFINITIONS:
        abort(404)
    uploads = [item for item in request.files.getlist("images") if item and item.filename]
    if not uploads:
        return redirect(url_for("admin_service_portfolios", message="Choose at least one photo.", message_type="err"))
    if len(uploads) > SERVICE_PORTFOLIO_MAX_IMAGES_PER_UPLOAD:
        return redirect(url_for("admin_service_portfolios", message=f"Upload no more than {SERVICE_PORTFOLIO_MAX_IMAGES_PER_UPLOAD} photos at a time.", message_type="err"))
    caption = _service_clean(request.form.get("caption"), 180)
    prepared = []
    batch_total = 0
    try:
        for upload in uploads:
            data = _construction_read_upload(upload, SERVICE_PORTFOLIO_MAX_IMAGE_BYTES)
            batch_total += len(data)
            if batch_total > SERVICE_PORTFOLIO_MAX_IMAGE_BATCH_BYTES:
                raise ValueError("Keep each portfolio photo upload batch at 60 MB or less.")
            mime_type, extension = _construction_detect_image_type(data)
            filename = _construction_safe_filename(upload.filename, f"portfolio{extension}")
            stem = os.path.splitext(filename)[0].strip(" .") or "portfolio"
            filename = f"{stem}{extension}"
            prepared.append((filename, mime_type, data, hashlib.sha256(data).hexdigest()))
    except ValueError as exc:
        return redirect(url_for("admin_service_portfolios", message=str(exc), message_type="err"))
    inserted = duplicates = 0
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute("SELECT COALESCE(MAX(display_order),0) FROM website_service_portfolio_assets WHERE service_key=%s", (service_key,))
            next_order = int(cur.fetchone()[0] or 0) + 10
            for filename, mime_type, data, digest in prepared:
                cur.execute(
                    """
                    INSERT INTO website_service_portfolio_assets
                        (service_key,filename,mime_type,file_bytes,byte_size,sha256,caption,alt_text,display_order,is_active)
                    VALUES(%s,%s,%s,%s,%s,%s,%s,%s,%s,TRUE)
                    ON CONFLICT (service_key,sha256) DO NOTHING RETURNING id
                    """,
                    (service_key,filename,mime_type,data,len(data),digest,caption or None,caption or SERVICE_PORTFOLIO_DEFINITIONS[service_key]["title"],next_order),
                )
                if cur.fetchone():
                    inserted += 1
                    next_order += 10
                else:
                    duplicates += 1
        conn.commit()
    message = f"Uploaded {inserted} photo{'s' if inserted!=1 else ''}."
    if duplicates:
        message += f" Skipped {duplicates} duplicate{'s' if duplicates!=1 else ''}."
    return redirect(url_for("admin_service_portfolios", message=message, _anchor=f"portfolio-{service_key.lower()}"))

