functions.admin_service_portfolio_delete:
def admin_service_portfolio_delete(service_key, asset_id):
    validate_csrf()
    if request.form.get("_ibrows_confirmed_action") != "1":
        abort(400)
    service_key = str(service_key or "").upper()
    if service_key not in SERVICE_PORTFOLIO_DEFINITIONS:
        abort(404)
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute("DELETE FROM website_service_portfolio_assets WHERE id=%s AND service_key=%s RETURNING id", (asset_id, service_key))
            if not cur.fetchone(): abort(404)
        conn.commit()
    return redirect(url_for("admin_service_portfolios", message="Portfolio item deleted."))

